/**
 * Calculate the number of whole days between two dates (b - a), in UTC.
 * @param {string} a YYYY-MM-DD format
 * @param {string} b YYYY-MM-DD format
 * @returns {number} whole days, can be negative if b < a
 */
export function daysBetween(a, b) {
  const dateA = new Date(`${a}T00:00:00Z`);
  const dateB = new Date(`${b}T00:00:00Z`);
  const diffMs = dateB - dateA;
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Get the last day of the month for a given date, in UTC.
 * @param {string} date YYYY-MM-DD format
 * @returns {string} YYYY-MM-DD format (the last day of that month)
 */
export function lastDayOfMonth(date) {
  const d = new Date(`${date}T00:00:00Z`);
  const year = d.getUTCFullYear();
  const month = d.getUTCMonth();
  // Create date for first day of next month, then subtract 1 day
  const nextMonthFirst = new Date(Date.UTC(year, month + 1, 1));
  const lastDay = new Date(nextMonthFirst.getTime() - 1000 * 60 * 60 * 24);
  return lastDay.toISOString().split('T')[0];
}

/**
 * Calculate due date based on payment terms, in UTC.
 * @param {string} issueDate YYYY-MM-DD format
 * @param {string} terms 'NET14', 'NET30', or 'EOM'
 * @returns {string} YYYY-MM-DD format
 */
export function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return lastDayOfMonth(issueDate);
    default:
      return null;
  }
}

