test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 3, unitPrice: 9500, discountPercent: 0, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 28500);
  assert.equal(totals.discount, 0);
  // VAT: 28500 * 21 / 100 = 5985
  assert.equal(totals.vat, 5985);
  assert.equal(totals.total, 28500 + 5985);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
      { qty: 50, unitPrice: 50, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 19000 + 120000 + 2500;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  // VAT: (19000 + 120000 + 2500) * 21 / 100 = 29715
  assert.equal(totals.vat, 29715);
  assert.equal(totals.total, expectedSubtotal + 29715);
});

test('invoiceTotals with empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }, // 10000, discount 1000, amount after discount 9000
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  // VAT on amount after discount: 9000 * 21 / 100 = 1890
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10000 - 1000 + 1890);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }, // 10000, discount 1000, amount 9000, vat 1890
      { qty: 5, unitPrice: 2000, discountPercent: 20, vatRate: 21 }, // 10000, discount 2000, amount 8000, vat 1680
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 3000);
  // VAT: 1890 + 1680 = 3570
  assert.equal(totals.vat, 3570);
  assert.equal(totals.total, 20000 - 3000 + 3570);
});

