test('lineVat computes VAT on amount after discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // Line total: 10000, discount: 1000, amount after discount: 9000
  // VAT: 9000 * 21 / 100 = 1890
  assert.equal(lineVat(line), 1890);
});

test('lineVat handles different VAT rates', () => {
  const line21 = { qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const line9 = { qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 9 };
  const line0 = { qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 0 };

  // All have amount 10000 after no discount
  assert.equal(lineVat(line21), 2100); // 10000 * 21 / 100
  assert.equal(lineVat(line9), 900); // 10000 * 9 / 100
  assert.equal(lineVat(line0), 0); // 10000 * 0 / 100
});

test('lineVat rounds fractional VAT', () => {
  const line = { qty: 3, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  // Amount: 300, VAT: 300 * 21 / 100 = 63
  assert.equal(lineVat(line), 63);
});

test('invoiceTotals sums VAT from all lines', () => {
