    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }, // 100000, discount 10000, amount 90000, vat 18900
      { qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 9 }, // 10000, discount 0, amount 10000, vat 900
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 110000);
  assert.equal(totals.discount, 10000);
